from pathlib import Path
p=Path('/mnt/data/HONRO_MAP_WORKSHOP_V2/src/app.js')
s=p.read_text()

def replace_func(name,new_body):
    global s
    marker=f'function {name}('
    a=s.index(marker)
    b=s.find('\nfunction ', a+len(marker))
    if b<0:
        b=s.find('\naddEventListener(', a+len(marker))
    if b<0:
        raise RuntimeError('next function not found '+name)
    s=s[:a]+new_body.rstrip()+s[b:]

# helpers after COLORS
needle="const COLORS={soil:'#514c40',grass:'#385334',moss:'#475f44',rock:'#575d5a',scree:'#4b4d46',mud:'#443a32',water:'#426975',charred:'#332f2b',stone:'#66665e',wood:'#574b37'};\n"
helpers=r'''const COLORS={soil:'#514c40',grass:'#385334',moss:'#475f44',rock:'#575d5a',scree:'#4b4d46',mud:'#443a32',water:'#426975',charred:'#332f2b',stone:'#66665e',wood:'#574b37'};

// Geometry helpers shared by human UI and Agent API.
function pointLineDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,n=dx*dx+dy*dy;if(!n)return dist(p,a);const t=clamp(((p.x-a.x)*dx+(p.y-a.y)*dy)/n,0,1),q={x:a.x+dx*t,y:a.y+dy*t};return dist(p,q)}
function rdpOpen(points,epsilon=0){if(!epsilon||points.length<=2)return points.map(p=>({...p}));let max=0,index=-1;for(let i=1;i<points.length-1;i++){const d=pointLineDistance(points[i],points[0],points.at(-1));if(d>max){max=d;index=i}}if(max<=epsilon||index<0)return[{...points[0]},{...points.at(-1)}];const l=rdpOpen(points.slice(0,index+1),epsilon),r=rdpOpen(points.slice(index),epsilon);return[...l.slice(0,-1),...r]}
function rdpClosed(points,epsilon=0){if(!epsilon||points.length<=3)return points.map(p=>({...p}));let pivot=1,max=0;for(let i=1;i<points.length;i++){const d=dist(points[0],points[i]);if(d>max){max=d;pivot=i}}const a=rdpOpen(points.slice(0,pivot+1),epsilon),b=rdpOpen([...points.slice(pivot),points[0]],epsilon);const out=[...a.slice(0,-1),...b.slice(0,-1)];return out.length>=3?out:points.slice(0,3).map(p=>({...p}))}
function pointInPoly(p,pts){let inside=false;for(let i=0,j=pts.length-1;i<pts.length;j=i++){const a=pts[i],b=pts[j];if(((a.y>p.y)!==(b.y>p.y))&&(p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y||1e-9)+a.x))inside=!inside}return inside}
function gridSnapPoint(p,size=project?.settings?.grid||40){const g=Math.max(2,+size||40);return{x:Math.round(p.x/g)*g,y:Math.round(p.y/g)*g}}
function terrainEditPoints(t){return t.type==='solid'?(t.points||[]):(t.control||[])}
function syncAssetCollision(a){if(a.collision.length)a.collision=deep(a.visual.filter(s=>s.type==='polygon').map(s=>s.points))}
function polylineNodeCount(st){return st.terrains.reduce((n,t)=>n+deriveTerrain(t).length,0)}
function assetNodeCount(a){return a.visual.reduce((n,sh)=>n+(sh.points?.length||0),0)}
function sceneStats(st){let elementNodes=0;for(const e of st.elements){const a=project.library.find(x=>x.id===e.assetId);if(a)elementNodes+=assetNodeCount(a)}return{terrainControl:st.terrains.reduce((n,t)=>n+terrainEditPoints(t).length,0),terrainDerived:polylineNodeCount(st),elementNodes,elementCount:st.elements.length,materialCount:st.materials.length,total:polylineNodeCount(st)+elementNodes}}
function visibleRect(canvas,view,margin=100){const w=canvas.clientWidth/view.zoom,h=canvas.clientHeight/view.zoom;return{left:view.x-w/2-margin,right:view.x+w/2+margin,top:view.y-h/2-margin,bottom:view.y+h/2+margin}}
function elementVisible(a,inst,vr){const b=assetBounds(a),cx=inst.x+(b.x+b.w/2)*inst.scale,cy=inst.y+(b.y+b.h/2)*inst.scale,r=Math.hypot(b.w,b.h)*Math.abs(inst.scale||1)*.65+30;return !(cx+r<vr.left||cx-r>vr.right||cy+r<vr.top||cy-r>vr.bottom)}
'''
assert needle in s
s=s.replace(needle,helpers,1)

# default project and runtime state
s=s.replace("settings:{grid:40,snap:true,autosave:true}","settings:{grid:40,snap:true,autosave:true,adaptiveLOD:true}")
s=s.replace("let project=loadAutosave()||newProject(), currentTab='stage', selectedAssetId=project.library[0]?.id, selected=null, selectedNode=-1, tool='select', materialKind='grass', placementAssetId='rock_large', unitKind='hound', eventKind='trigger', previewProject=null;\nlet history=[],future=[],stageView={x:0,y:0,zoom:1},elementView={x:0,y:0,zoom:1},playState=null,drawStroke=[],paintStroke=[],scatterStamp=0;",
"let project=loadAutosave()||newProject(), currentTab='stage', selectedAssetId=project.library[0]?.id, selected=null, selectedNode=-1, selectedShapeIndex=-1, tool='select', materialKind='grass', placementAssetId='rock_large', unitKind='hound', eventKind='trigger', previewProject=null;\nlet history=[],future=[],stageView={x:0,y:0,zoom:1},elementView={x:0,y:0,zoom:1},playState=null,drawStroke=[],paintStroke=[],solidDraft=[],elementPolygonDraft=[],scatterStamp=0;")

replace_func('loadAutosave',r'''function loadAutosave(){try{const x=JSON.parse(localStorage.getItem('honro-workshop-v1'));if(!x?.version)return null;x.settings={grid:40,snap:true,autosave:true,adaptiveLOD:true,...x.settings};for(const st of x.stages||[])for(const t of st.terrains||[]){t.detail={spacing:18,roughness:0,seed:1,optimizeEpsilon:0,...t.detail}}return x}catch(e){return null}}''')

# terrain derivation + surface functions
replace_func('deriveTerrain',r'''function deriveTerrain(t){
 if(t.type==='solid')return (t.points||[]).map(p=>({...p}));
 if(t.type!=='ground'&&t.type!=='platform')return (t.points||[]).map(p=>({...p}));
 const c=[...(t.control||[])].sort((a,b)=>a.x-b.x);if(c.length<2)return c;
 const spacing=Math.max(6,t.detail?.spacing||24),rough=t.detail?.roughness||0,eps=Math.max(0,+t.detail?.optimizeEpsilon||0);
 const sig=`${spacing}|${rough}|${t.detail?.seed||1}|${eps}|`+c.map(p=>`${round(p.x,2)},${round(p.y,2)}`).join(';');
 if(t.__derivedCache?.sig===sig)return t.__derivedCache.points;
 const r=seeded(t.detail?.seed||1),raw=[];for(let i=0;i<c.length-1;i++){const a=c[i],b=c[i+1],n=Math.max(1,Math.ceil(Math.abs(b.x-a.x)/spacing));for(let k=0;k<n;k++){const u=k/n,sm=u*u*(3-2*u),edge=Math.sin(Math.PI*u),micro=(r()*2-1)*rough*edge+Math.sin((a.x+k*37)*.017)*rough*.26;raw.push({x:a.x+(b.x-a.x)*u,y:a.y+(b.y-a.y)*sm+micro})}}raw.push({...c.at(-1)});
 const points=eps?rdpOpen(raw,eps):raw;try{Object.defineProperty(t,'__derivedCache',{value:{sig,points},writable:true,configurable:true,enumerable:false})}catch{}return points
}''')

# insert terrain surface helpers before sampleTerrainY replacement
replace_func('sampleTerrainY',r'''function terrainSurfaceYs(t,x){
 if(t.type!=='solid'){const pts=deriveTerrain(t),ys=[];for(let i=0;i<pts.length-1;i++){const a=pts[i],b=pts[i+1];if(x>=Math.min(a.x,b.x)-1e-6&&x<=Math.max(a.x,b.x)+1e-6&&Math.abs(b.x-a.x)>1e-6){const u=(x-a.x)/(b.x-a.x);ys.push(a.y+(b.y-a.y)*u)}}return ys}
 const pts=t.points||[],ys=[];for(let i=0;i<pts.length;i++){const a=pts[i],b=pts[(i+1)%pts.length];if((x>=Math.min(a.x,b.x)-1e-6&&x<=Math.max(a.x,b.x)+1e-6)&&Math.abs(b.x-a.x)>1e-6){const u=(x-a.x)/(b.x-a.x);if(u>=-1e-6&&u<=1+1e-6)ys.push(a.y+(b.y-a.y)*u)}}return [...new Set(ys.map(v=>round(v,4)))].sort((a,b)=>a-b)
}
function sampleTerrainY(t,x,reference=Infinity){const ys=terrainSurfaceYs(t,x);if(!ys.length)return null;if(Number.isFinite(reference))return ys.reduce((a,b)=>Math.abs(a-reference)<=Math.abs(b-reference)?a:b);return Math.min(...ys)}''')

replace_func('nearestSurface',r'''function nearestSurface(st,x,y=Infinity){let best=null;for(const t of st.terrains){for(const sy of terrainSurfaceYs(t,x)){const d=Number.isFinite(y)?Math.abs(sy-y):sy;if(!best||d<best.d)best={terrain:t,y:sy,d}}}return best}''')

replace_func('materialPolygon',r'''function materialPolygon(st,m){const t=st.terrains.find(x=>x.id===m.terrainId);if(!t||t.type==='solid')return[];const pts=deriveTerrain(t).filter(p=>p.x>=Math.min(m.x1,m.x2)&&p.x<=Math.max(m.x1,m.x2));if(pts.length<2)return[];const depth=m.depth||24;if(m.kind==='water'){const level=Math.min(pts[0].y,pts.at(-1).y)+Math.min(34,depth);return[{x:pts[0].x,y:level},{x:pts.at(-1).x,y:level},...pts.slice().reverse()]}return[...pts,...pts.slice().reverse().map(p=>({x:p.x,y:p.y+depth}))]}''')

replace_func('snapElement',r'''function snapElement(st,inst){if(!inst.snap)return inst;const sf=nearestSurface(st,inst.x,inst.y);if(sf)inst.y=sf.y;return inst}''')

