# Stage inspector UI
replace_func('stageInspectorHtml',r'''function stageInspectorHtml(st){const stats=sceneStats(st);let body=`<div class="panel-section"><div class="panel-title"><span>STAGE</span></div><div class="row"><label>이름</label><input id="stageName" class="field" value="${esc(st.name)}"></div><div class="split"><div><label class="node-label">Width</label><input id="stageW" class="field num" type="number" value="${st.width}"></div><div><label class="node-label">Height</label><input id="stageH" class="field num" type="number" value="${st.height}"></div></div><div class="row"><label>Backdrop</label><select id="stageBackdrop" class="field">${['forest','ravine','river','village','shrine','bridge'].map(x=>`<option ${st.backdrop===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="split"><div><label class="node-label">Grid</label><input id="gridSize" class="field num" type="number" min="4" max="256" value="${project.settings.grid||40}"></div><div><label class="node-label">Adaptive LOD</label><div style="padding:6px 0"><input id="adaptiveLOD" type="checkbox" ${project.settings.adaptiveLOD!==false?'checked':''}> zoom-out 간소화</div></div></div></div>`;
 body+=`<div class="panel-section"><div class="panel-title"><span>PERFORMANCE</span></div><div class="perf-grid"><span>Terrain</span><strong>${stats.terrainDerived}</strong><span>Element vector</span><strong>${stats.elementNodes}</strong><span>Total nodes</span><strong class="${stats.total>6000?'warn':'good'}">${stats.total}</strong></div><div class="row"><label>LOD ε</label><input id="stageOptimizeEps" class="field" type="number" min="0" max="80" step="1" value="4"><button id="optimizeStage" class="btn sm">전체 적용</button></div><div class="muted node-label">ε가 클수록 export/render node가 줄어듭니다. 원본 control은 유지됩니다.</div></div>`;
 if(!selected)return body+`<div class="panel-section"><div class="panel-title"><span>TOOL</span></div>${toolHelp()}</div><div class="panel-section"><div class="panel-title"><span>MATERIAL</span></div>${materialGrid()}</div>`;
 const o=getSelected(st);if(!o)return body;
 body+=`<div class="panel-section"><div class="panel-title"><span>SELECTED · ${selected.type.toUpperCase()}</span><button id="deleteSelected" class="btn sm danger">삭제</button></div><div class="row"><label>ID</label><input class="field" value="${esc(o.id)}" disabled></div>`;
 if(selected.type==='terrain'){
  const raw=(o.type==='solid'?(o.points||[]):(()=>{const old=o.detail?.optimizeEpsilon;o.detail.optimizeEpsilon=0;const p=deriveTerrain(o).length;o.detail.optimizeEpsilon=old;delete o.__derivedCache;return Array(p).fill(0)})()).length,optimized=deriveTerrain(o).length;
  body+=`<div class="row"><label>이름</label><input id="objName" class="field" value="${esc(o.name||o.id)}"></div><div class="row"><label>Type</label><strong>${o.type}</strong></div><div class="row"><label>Material</label><select id="terrainBase" class="field">${Object.keys(COLORS).map(x=>`<option ${o.baseMaterial===x?'selected':''}>${x}</option>`).join('')}</select></div>`;
  if(o.type!=='solid')body+=`<div class="split"><div><label class="node-label">Generated spacing</label><input id="terrainSpacing" type="number" class="field" value="${o.detail?.spacing||20}"></div><div><label class="node-label">Roughness</label><input id="terrainRough" type="number" class="field" value="${o.detail?.roughness||0}"></div></div><div class="row"><label>Optimize ε</label><input id="terrainOptimize" type="number" class="field" min="0" max="80" step="1" value="${o.detail?.optimizeEpsilon||0}"></div><div class="row"><button id="roughenBtn" class="btn sm">Detail randomize</button><button id="smoothBtn" class="btn sm">Smooth controls</button></div><div class="muted node-label">Control ${o.control.length} · Raw ${raw} → Optimized ${optimized}</div>`;
  else body+=`<div class="muted node-label">Closed solid polygon · ${o.points?.length||0} vertices · overhang/cave 지원</div>`;
 }
 if(selected.type==='element'){const a=project.library.find(x=>x.id===o.assetId);body+=`<div class="row"><label>Asset</label><div>${esc(a?.name||o.assetId)}</div></div><div class="split"><div><label class="node-label">Scale</label><input id="elScale" class="field" type="number" step=".05" value="${o.scale}"></div><div><label class="node-label">Rotation°</label><input id="elRot" class="field" type="number" value="${round(o.rotation*180/Math.PI)}"></div></div><div class="row"><label>Layer</label><select id="elLayer" class="field">${st.layers.map(l=>`<option value="${l.id}" ${o.layer===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div><div class="row"><label>Surface snap</label><input id="elSnap" type="checkbox" ${o.snap?'checked':''}></div>`}
 if(selected.type==='unit'){body+=`<div class="row"><label>종류</label><select id="unitType" class="field">${unitTypes().map(x=>`<option ${o.kind===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="row"><label>Team</label><select id="unitTeam" class="field">${['player','ally','enemy','npc'].map(x=>`<option ${o.team===x?'selected':''}>${x}</option>`).join('')}</select></div>`}
 if(selected.type==='event'){body+=`<div class="row"><label>Type</label><select id="eventType" class="field">${['trigger','objective','interaction','spawn','dialogue'].map(x=>`<option ${o.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="row"><label>Label</label><input id="eventLabel" class="field" value="${esc(o.label||'')}"></div>`}
 return body+`</div><div class="panel-section"><div class="panel-title"><span>MATERIAL</span></div>${materialGrid()}</div>`}''')

replace_func('toolHelp',r'''function toolHelp(){const h={select:'클릭 선택 · 드래그 이동 · Terrain/solid node 직접 편집 · Ctrl+드래그: Grid snap',terrain:'마우스로 지표면을 그리면 고밀도 ground로 변환',solid:'클릭으로 닫힌 polygon 점 추가 · 더블클릭/Enter로 완료 · 동굴/overhang 제작',material:'지면 위를 드래그하여 material 구간 paint',place:'Library 요소 배치 후 자동으로 선택모드 · surface snap',scatter:'브러시 영역에 요소를 자연스럽게 scatter',unit:'아군/적/NPC 배치',event:'Trigger/Objective/Event marker 배치',pan:'드래그로 카메라 이동'};return`<div class="muted" style="font-size:10px;line-height:1.7">${h[tool]||''}</div>`}''')

replace_func('bindStageInspector',r'''function bindStageInspector(st){
 const change=(id,fn)=>{const e=$('#'+id);if(e)e.onchange=()=>commit('속성 변경',()=>fn(realStage(),e))};change('stageName',(s,e)=>s.name=e.value);change('stageW',(s,e)=>s.width=Math.max(800,+e.value||s.width));change('stageH',(s,e)=>s.height=Math.max(600,+e.value||s.height));change('stageBackdrop',(s,e)=>s.backdrop=e.value);change('objName',(s,e)=>{const o=getSelected(s);o.name=e.value});change('terrainBase',(s,e)=>getSelected(s).baseMaterial=e.value);change('terrainSpacing',(s,e)=>getSelected(s).detail.spacing=clamp(+e.value||20,6,180));change('terrainRough',(s,e)=>getSelected(s).detail.roughness=clamp(+e.value||0,0,80));change('terrainOptimize',(s,e)=>getSelected(s).detail.optimizeEpsilon=clamp(+e.value||0,0,100));change('elScale',(s,e)=>getSelected(s).scale=clamp(+e.value||1,.1,8));change('elRot',(s,e)=>getSelected(s).rotation=(+e.value||0)*Math.PI/180);change('elLayer',(s,e)=>getSelected(s).layer=e.value);change('gridSize',(s,e)=>project.settings.grid=clamp(+e.value||40,4,256));
 const lod=$('#adaptiveLOD');if(lod)lod.onchange=()=>commit('Adaptive LOD 변경',p=>p.settings.adaptiveLOD=lod.checked);const all=$('#optimizeStage');if(all)all.onclick=()=>{const eps=clamp(+$('#stageOptimizeEps').value||0,0,100);commit(`Stage terrain LOD ε=${eps}`,()=>{for(const t of realStage().terrains)if(t.type!=='solid'){t.detail??={};t.detail.optimizeEpsilon=eps;delete t.__derivedCache}})};
 const snap=$('#elSnap');if(snap)snap.onchange=()=>commit('Snap 변경',()=>getSelected(realStage()).snap=snap.checked);change('unitType',(s,e)=>getSelected(s).kind=e.value);change('unitTeam',(s,e)=>getSelected(s).team=e.value);change('eventType',(s,e)=>getSelected(s).type=e.value);change('eventLabel',(s,e)=>getSelected(s).label=e.value);
 const d=$('#deleteSelected');if(d)d.onclick=deleteSelection;const r=$('#roughenBtn');if(r)r.onclick=()=>commit('Terrain detail randomize',()=>{const o=getSelected(realStage());o.detail.seed=(o.detail.seed||1)+17;delete o.__derivedCache});const sm=$('#smoothBtn');if(sm)sm.onclick=()=>commit('Terrain controls smooth',()=>{const o=getSelected(realStage());o.control=o.control.map((p,i,a)=>i&&i<a.length-1?{x:p.x,y:(a[i-1].y+p.y*2+a[i+1].y)/4}:p);delete o.__derivedCache});$$('[data-mat]').forEach(b=>b.onclick=()=>{materialKind=b.dataset.mat;tool='material';renderAll()});const br=$('#brushRange');if(br){br.oninput=()=>$('#brushVal').textContent=br.value}
}''')

