old="case'terrain.add':{const t={id:c.id||uid('terrain'),name:c.name||'Agent Ground',type:c.type||'ground',control:(c.control||[]).map(([x,y])=>({x,y})),floor:c.floor||st.height+100,baseMaterial:c.material||'soil',detail:{spacing:c.spacing||18,roughness:c.roughness||6,seed:c.seed||42},layer:'terrain'};st.terrains.push(t);break}case'terrain.roughen':"
new="case'terrain.add':{const t={id:c.id||uid('terrain'),name:c.name||'Agent Ground',type:c.type||'ground',control:(c.control||[]).map(([x,y])=>({x,y})),floor:c.floor||st.height+100,baseMaterial:c.material||'soil',detail:{spacing:c.spacing||18,roughness:c.roughness||6,seed:c.seed||42,optimizeEpsilon:c.optimizeEpsilon||0},layer:'terrain'};st.terrains.push(t);break}case'terrain.addSolid':{st.terrains.push({id:c.id||uid('solid'),name:c.name||'Agent Solid',type:'solid',points:(c.points||[]).map(([x,y])=>({x,y})),baseMaterial:c.material||'rock',breakable:!!c.breakable,layer:'terrain'});break}case'terrain.optimize':{const t=st.terrains.find(x=>x.id===c.id);if(t&&t.type!=='solid'){t.detail??={};t.detail.optimizeEpsilon=clamp(c.epsilon??0,0,100);delete t.__derivedCache}break}case'terrain.roughen':"
assert old in s
