# keyboard support: patch bindTop manually
old="document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return}if(e.key==='Delete'||e.key==='Backspace'){if(['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;deleteSelection()}if(e.key==='Escape'){selected=null;selectedNode=-1;renderAll()}})"
new="document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return}if(e.key==='Enter'){if(currentTab==='stage'&&tool==='solid')finalizeSolid();else if(currentTab==='element'&&elementTool==='polygon')finalizeElementPolygon();return}if(e.key==='Delete'||e.key==='Backspace'){if(['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(currentTab==='element'){const a=activeAsset();if(selectedNode>=0){const n=nodeByGlobal(a,selectedNode);if(n&&n.shape.points.length>3)commit('Vertex 삭제',()=>{n.shape.points.splice(n.index,1);syncAssetCollision(a);selectedNode=-1})}else if(selectedShapeIndex>=0&&a.visual.length>1)commit('Polygon 삭제',()=>{a.visual.splice(selectedShapeIndex,1);syncAssetCollision(a);selectedShapeIndex=-1});return}deleteSelection()}if(e.key==='Escape'){selected=null;selectedNode=-1;selectedShapeIndex=-1;solidDraft=[];elementPolygonDraft=[];renderAll()}})"
assert old in s
s=s.replace(old,new,1)

